int main() {
    // Define the array
    int array[] = {1, 2, 3, 4, 5, 6};

    // Identify the element (let's say we're interested in the 3rd element)
    int element_index = 2;

    // Calculate the offset (considering each element is 4 bytes)
    size_t offset = (element_index * sizeof(int)) + ((element_index > 0)? 1 : 0);

